import React from "react";
import { Container, Row, Col } from "react-bootstrap";
import shows from "../data/shows.json";

export default function Shows() {
  const upcoming = Array.isArray(shows) ? shows : [];

  return (
    <section id="shows" className="shows-area section-padding-100">
      <Container>
        <Row>
          <Col>
            <div className="section-heading style-2 text-center mb-4">
              <p>On the Road</p>
              <h2>Upcoming Shows</h2>
            </div>
          </Col>
        </Row>

        <Row className="justify-content-center">
          {upcoming.map((s, i) => {
            // build a clean aria-label from available fields
            const parts = [
              s.venue && s.venue.trim(),
              s.address && s.address.trim(),
              s.city && s.city.trim(),
            ].filter(Boolean);

            const ariaLabel = parts.length
              ? `${parts.join(", ")}${s.date ? ` on ${s.date.trim()}` : ""}`
              : s.venue || "";

            return (
              <Col key={i} xs={12} md={4} className="mb-3">
                <div className="single-show text-center p-3 border rounded bg-white">
                  {s.img && (
                    <picture>
                      <source
                        type="image/avif"
                        srcSet={`${s.img.replace(
                          /\.jpg$/,
                          "-480.avif"
                        )} 480w, ${s.img.replace(
                          /\.jpg$/,
                          "-800.avif"
                        )} 800w, ${s.img.replace(
                          /\.jpg$/,
                          "-1200.avif"
                        )} 1200w`}
                        sizes="(max-width: 600px) 100vw, 33vw"
                      />
                      <source
                        type="image/webp"
                        srcSet={`${s.img.replace(
                          /\.jpg$/,
                          "-480.webp"
                        )} 480w, ${s.img.replace(
                          /\.jpg$/,
                          "-800.webp"
                        )} 800w, ${s.img.replace(
                          /\.jpg$/,
                          "-1200.webp"
                        )} 1200w`}
                        sizes="(max-width: 600px) 100vw, 33vw"
                      />
                      <img
                        /* Use the original image as the `src` so we always have a valid
                           fallback when generated variants (e.g. -480.jpg) are missing.
                           Keep the -variant srcSet entries so browsers that have those
                           files will pick them, and append the original image at the
                           end of the srcSet as a last-resort option. */
                        src={s.img}
                        srcSet={`${s.img.replace(
                          /\.jpg$/,
                          "-480.jpg"
                        )} 480w, ${s.img.replace(
                          /\.jpg$/,
                          "-800.jpg"
                        )} 800w, ${s.img.replace(
                          /\.jpg$/,
                          "-1200.jpg"
                        )} 1200w, ${s.img} 2000w`}
                        sizes="(max-width: 600px) 100vw, 33vw"
                        alt={`${s.venue}${s.address ? ` — ${s.address}` : ""}`}
                        aria-label={ariaLabel}
                        className="img-fluid mb-2 rounded"
                        loading="lazy"
                      />
                    </picture>
                  )}
                  <h5 className="mb-1">{s.venue}</h5>
                  <p className="mb-1 text-muted small">
                    {[s.address, s.city].filter(Boolean).join(", ")}
                  </p>
                  <p className="mt-2 fw-bold">{s.date}</p>
                </div>
              </Col>
            );
          })}
        </Row>
      </Container>
    </section>
  );
}
